import requests

def get_anagrams(scrambled_list):
    word_url = "https://raw.githubusercontent.com/dwyl/english-words/master/words_alpha.txt"
    words = requests.get(word_url).text.splitlines()
    word_dict = {}
    for w in words:
        length = len(w)
        if length not in word_dict:
            word_dict[length] = []
        word_dict[length].append(w)

    results = {}
    for scram in scrambled_list:
        low_scram = scram.lower()
        cnt = Counter(low_scram)
        l = len(scram)
        matches = [w for w in word_dict.get(l, []) if Counter(w.lower()) == cnt]
        results[scram] = matches
    return results

